import {tilePreview} from './editor-tool-previews.js';
import {STRUCTURE_PRESETS} from './editor-structure-presets.js';
const GROUPS=[
 ['inspect','↖','Select',['inspect']],['terrain','▦','Tiles',['texture','floor','water','bridge']],
 ['objects','▣','Objects',['prop']],['structures','⌂','Structures',['room','prefab']],
 ['roofs','⌑','Roofs',['roof-tile']],['walls','▥','Walls',['wall','door']],
 ['cliffs','◩','Cliffs',['cliff','cliff-climb']],['ramps','◿','Ramps',['ramp','ramp-bank']],
 ['people','♟','People',['guard','npc']],['locations','⚑','Locations',['squad','exit']],
 ['access','⇅','Access',['stairs','ladder','roof']],['foliage','♣','Foliage',['foliage-cover']],
 ['erase','⌫','Erase',['erase-prop','remove-guard','erase-edge','erase-tile','erase-stairs','erase-roof','erase-cliff','clear-foliage']],['library','▤','Blocks',[]]
];
export function installWorkbench({rotate,clearSelection}){
 const $=id=>document.getElementById(id),left=document.querySelector('.tools'),right=document.querySelector('.properties'),panel=$('editing-tools'),library=$('workspace').closest('section'),design=$('design-name').closest('section');
 const settings=document.createElement('dialog');settings.id='editor-settings';settings.innerHTML='<div class="settings-heading"><h1>Editor settings</h1><button id="close-settings" aria-label="Close settings">✕</button></div><div id="settings-content"></div>';document.body.append(settings);const content=$('settings-content');
 // Move established controls intact so their saved state and handlers survive the layout change.
 for(const child of [...left.children])if(child!==panel&&child!==library)content.append(child);
 content.append(design,library);for(const d of [...right.querySelectorAll(':scope > details')])content.append(d);
 for(const node of [...right.children])if(node.tagName==='P'&&!node.id||node.tagName==='H2'&&node.textContent==='Design view')content.append(node);
 const toolsLabel=$('edit-tool').closest('label');toolsLabel.hidden=true;panel.prepend(toolsLabel);right.prepend(panel);panel.querySelector('h2').remove();
 const head=document.createElement('div');head.className='context-heading';head.innerHTML='<p class="eyebrow">Tool options</p><h1 id="active-tool-name">Select</h1><label>Mode<select id="tool-mode"></select></label><p id="tool-description"></p>';panel.prepend(head);
 const stroke=document.createElement('label');stroke.id='stroke-mode-label';stroke.innerHTML='Paint area<select id="stroke-mode"><option value="single">Single tile</option><option value="rectangle">Drag rectangle</option></select>';head.append(stroke);
 const preset=document.createElement('label');preset.id='structure-preset-label';preset.innerHTML='Preset structure<select id="structure-preset"></select>';for(const [id,p]of Object.entries(STRUCTURE_PRESETS))preset.querySelector('select').add(new Option(p.name,id));head.append(preset);$('structure-preset').onchange=()=>{$('edit-tool').value=$('structure-preset').value==='room'?'room':'prefab';$('edit-tool').dispatchEvent(new Event('change'));};
 const gallery=document.createElement('section');gallery.id='tile-gallery';gallery.innerHTML='<label>Find a style<input id="tile-search" type="search" placeholder="Grass, concrete, diagonal…"></label><div id="tile-swatches"></div>';head.append(gallery);
 left.innerHTML='<div class="remote-top"><button id="settings-button" title="Editor settings">⚙<span>Settings</span></button><button id="quick-save-map" title="Save this design">▣<span>Save</span></button></div><p class="remote-caption">BUILD TOOLS</p><nav id="tool-palette" aria-label="Build tools"></nav><div class="remote-view"><button id="quick-overview">Overview</button><button id="quick-home">Center</button><button id="quick-playtest">▶ Playtest</button></div>';
 for(const [id,icon,label]of GROUPS){const b=document.createElement('button');b.dataset.group=id;b.innerHTML=`<span class="tool-symbol" aria-hidden="true">${icon}</span><span>${label}</span>`;b.title=label;b.onclick=()=>activate(id);$('tool-palette').append(b);}
 $('settings-button').onclick=()=>settings.showModal();$('close-settings').onclick=()=>settings.close();$('quick-save-map').onclick=()=>$('save-map').click();$('quick-overview').onclick=()=>$('overview').click();$('quick-home').onclick=()=>$('home').click();$('quick-playtest').onclick=()=>$('playtest').click();
 const bottom=document.createElement('footer');bottom.id='editor-bottom';bottom.innerHTML='<div class="altitude" aria-label="Build altitude"><span>Altitude</span></div><div class="edit-actions"></div><span id="altitude-note"></span>';document.body.append(bottom);for(let i=0;i<4;i++){const b=document.createElement('button');b.textContent=i+1;b.dataset.level=i;b.title=i===3?'4 · Decorative roofs only':`${i+1} · Playable level`;b.onclick=()=>{$('floor').value=i;$('floor').dispatchEvent(new Event('change'));};bottom.querySelector('.altitude').append(b);}for(const id of ['undo','redo','rotate-selected','delete-selected'])bottom.querySelector('.edit-actions').append($(id));$('rotate-selected').textContent='↻ Rotate';$('delete-selected').textContent='⌫ Delete selected';$('rotate-selected').onclick=rotate;
 function floorSync(){for(const b of bottom.querySelectorAll('[data-level]'))b.setAttribute('aria-pressed',b.dataset.level===$('floor').value);$('altitude-note').textContent=$('floor').value==='3'?'Builder roof layer · not walkable':'';if($('floor').value==='3')activate('roofs');} $('floor').addEventListener('change',floorSync);floorSync();
 const propOptions=[...$('prop-kind').options].map(o=>({value:o.value,label:o.textContent}));const allOptions=[...$('edit-tool').options].map(o=>({value:o.value,label:o.textContent.replace(/^Prop$/,'Objects')}));let group='inspect',remember={};
 const children=[...panel.children].filter(n=>n!==head&&n!==toolsLabel),owner=(id)=>{const e=$(id);return children.find(n=>n===e||n.contains(e));};
 const rules=new Map();function showFor(ids,tools){for(const id of ids){const n=owner(id);if(n)rules.set(n,[...new Set([...(rules.get(n)||[]),...tools])]);}}
 showFor(['ground-kind'],['texture']);showFor(['prop-kind'],['prop','roof-tile']);showFor(['edge-kind'],['wall']);showFor(['room-width','room-height'],['room']);showFor(['rotated'],['prop','room','roof-tile','prefab']);showFor(['ramp-options'],['ramp']);showFor(['bank-options'],['ramp-bank']);showFor(['cliff-options'],['cliff']);showFor(['foliage-help'],['foliage-cover','clear-foliage']);showFor(['unit-species'],['guard','npc','squad']);showFor(['light-mode','apply-light-mode','apply-fixture-condition','aim-spotlight','finish-spotlight','add-lookout'],['prop','inspect']);showFor(['ramp-bank-surface','add-ramp-banks'],['ramp','inspect']);showFor(['use-selected'],['inspect']);showFor(['apply-door-lock'],['inspect','wall','door']);
 for(const node of children)if(node.tagName==='P'){const text=node.textContent;rules.set(node,text.startsWith('Cliff climb')?['cliff-climb']:text.startsWith('Ramp props')?['ramp']:text.startsWith('Lookouts')||text.startsWith('Select a spotlight')||text.startsWith('Light reaches')?['prop','inspect']:[]);}
 function swatches(){const box=$('tile-swatches');box.replaceChildren();const tool=$('edit-tool').value;if(!['texture','floor','water','bridge'].includes(tool))return;const entries=tool==='texture'?[...$('ground-kind').options].map(o=>({id:o.value,name:o.textContent})):[{id:tool,name:tool}];for(const item of entries.filter(o=>o.name.toLowerCase().includes($('tile-search').value.toLowerCase()))){const b=document.createElement('button');b.type='button';b.title=item.name;b.setAttribute('aria-label',item.name);b.setAttribute('aria-pressed',tool!=='texture'||$('ground-kind').value===item.id);const img=new Image();img.src=tilePreview(item.id);img.alt='';const text=document.createElement('span');text.textContent=item.name.replaceAll('-',' ');b.append(img,text);b.onclick=()=>{if(tool==='texture'){$('ground-kind').value=item.id;$('ground-kind').dispatchEvent(new Event('change'));}swatches();};box.append(b);}}
 $('tile-search').oninput=swatches;$('ground-kind').addEventListener('change',swatches);
 function context(){const tool=$('edit-tool').value;const current=GROUPS.find(g=>g[3].includes(tool));if(current)group=current[0];remember[group]=tool;const spec=GROUPS.find(g=>g[0]===group);if(['prop','roof-tile'].includes(tool)){const value=$('prop-kind').value,items=propOptions.filter(o=>tool==='roof-tile'?o.value.startsWith('roof-'):!o.value.startsWith('roof-'));$('prop-kind').replaceChildren(...items.map(o=>new Option(o.label,o.value)));if(items.some(o=>o.value===value))$('prop-kind').value=value;}$('active-tool-name').textContent=spec[2];for(const b of $('tool-palette').children)b.setAttribute('aria-pressed',b.dataset.group===group);$('tool-mode').replaceChildren(...allOptions.filter(o=>spec[3].includes(o.value)).map(o=>new Option(o.label,o.value)));$('tool-mode').value=tool;$('tool-mode').closest('label').hidden=spec[3].length<2||group==='structures';
 for(const node of children){const allowed=rules.get(node);if(allowed)node.hidden=!allowed.includes(tool);else node.hidden=false;}toolsLabel.hidden=true;head.hidden=false;
 $('stroke-mode-label').hidden=!['texture','floor','water','bridge','cliff','foliage-cover','clear-foliage','erase-tile','erase-cliff'].includes(tool);gallery.hidden=!['texture','floor','water','bridge'].includes(tool);preset.hidden=group!=='structures';$('tool-description').textContent=group==='structures'?'Stamp a small structure. Choose a preset, rotate its footprint, then click to place.':group==='erase'?'Choose what to erase. Undo restores a completed edit.':group==='locations'?'Place squad starting slots or the travel marker.':group==='roofs'?'Choose a roof pattern and an altitude. Level 4 is decorative and cannot be reached by characters.':'';
 if(group!=='library'&&library.parentNode===panel)content.append(library);swatches();}
 function activate(id){group=id;if(id==='library'){head.hidden=false;for(const n of children)n.hidden=true;gallery.hidden=true;preset.hidden=true;stroke.hidden=true;$('tool-mode').closest('label').hidden=true;$('active-tool-name').textContent='Blocks & generation';$('tool-description').textContent='Save and place reusable 24 × 24 building blocks.';panel.append(library);library.hidden=false;$('edit-tool').value='inspect';clearSelection();for(const b of $('tool-palette').children)b.setAttribute('aria-pressed',b.dataset.group===id);return;}const spec=GROUPS.find(g=>g[0]===id);$('edit-tool').value=remember[id]||spec[3][0];$('edit-tool').dispatchEvent(new Event('change'));clearSelection();}
 $('tool-mode').onchange=()=>{$('edit-tool').value=$('tool-mode').value;$('edit-tool').dispatchEvent(new Event('change'));};$('edit-tool').addEventListener('change',context);
 document.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select,[contenteditable=true]')||settings.open||e.ctrlKey||e.metaKey||e.altKey)return;if(/^[1-4]$/.test(e.key)){e.preventDefault();bottom.querySelector(`[data-level="${+e.key-1}"]`).click();}});
 context();return {context,floorSync};
}
